"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "cpu": "450m"
        }
      }
    }
  },
  "expected_effect": "Raises the CPU limit of the app container to 450m, reducing throttling and allowing the app to use more CPU without being constrained.",
  "rationale": "The current version's app uses 0.28 CPU (93.3% of its 0.3 limit) and is throttled 57% of the time. The previous version had a lower limit (0.2) but was also throttled. Increasing the limit to 450m (1.5x current) should alleviate throttling without requiring node-level changes. The logs confirm the app is consistently behind, indicating sustained CPU pressure.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-rollout_history", "ev-container_logs_tail", "ev-themis_fix"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "rollout_changed_the_app", "throttling_came_with_rollout"]
}
